        meadow = mix(meadow, mix(vec3(0.95, 0.85, 0.6), vec3(0.9, 0.4, 0.06), n3(p * 31.0)), fl * 0.6 * smoothstep(40.0, 8.0, dist));
        // Basalt plateaus split into hexagonal columns.
